#!/usr/bin/env python3
"""Shared loading, normalization and call-splitting for the router pipeline.

Two things every script here must get right, both learned the hard way:

1. `export/` contains a SYNTHETIC chunk (`trajectories_v1_00.jsonl`, 153 lines from
   make_synthetic_sample.py) alongside the real one. `load_trajectories.iter_requests`
   globs `export/*.jsonl` and silently blends them. `real_requests()` filters to the
   real chunk only.

2. Redaction placeholders (`PII_PERSON_7`, `<COMPANY_A>`, ...) make identical templates
   look like distinct documents: the longest common prefix across all 1000 system
   prompts is 8 characters ("You are "). Normalize before any text comparison.

All token counts are ESTIMATES (serialized chars / 4). The export has no `usage` field.
Say so wherever a number is reported.
"""
import json, re, sys, hashlib
from pathlib import Path

REAL_CHUNK = "trajectories_v1_01.jsonl"

# ---------------------------------------------------------------- loading

def real_requests(export_dir="export", chunk=REAL_CHUNK):
    """Yield every request of the REAL chunk only (never the synthetic sample)."""
    p = Path(export_dir) / chunk
    if not p.exists():
        sys.exit(f"missing {p}. Extract the real export first.")
    with open(p, encoding="utf-8") as f:
        for line in f:
            if line.strip():
                yield json.loads(line)

def est_tokens(obj):
    """Crude token estimate: serialized chars / 4. ESTIMATE — there is no usage field."""
    return len(json.dumps(obj, ensure_ascii=False)) // 4

def family(model):
    return "claude" if model.startswith("claude") else "gpt"

# ---------------------------------------------------------------- item helpers

MODEL_ITEM_TYPES = {"reasoning", "function_call", "custom_tool_call"}

def is_model_item(it):
    """True if the item was produced BY the model (as opposed to the environment)."""
    if it.get("role") == "assistant":
        return True
    return it.get("type") in MODEL_ITEM_TYPES

def item_type(it):
    return "message:" + it["role"] if "role" in it else it.get("type", "?")

def item_text(it):
    c = it.get("content")
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        return "".join(p.get("text", "") for p in c if isinstance(p, dict))
    return ""

def tool_calls(items):
    """Every model-issued tool call in an input, as (name, args_string)."""
    out = []
    for it in items:
        if it.get("type") == "function_call":
            out.append((it.get("name", ""), str(it.get("arguments", ""))))
        elif it.get("type") == "custom_tool_call":
